import { delay, http, HttpResponse, type HttpHandler } from 'msw';
import { REQUEST_ID_HEADER } from '../client';
import type { AdminErrorEnvelope } from '../errors';
import type { OperationResponse, SessionUser } from '../types';
import { contractMocks } from './contract.gen';
import type { OperationId } from './types';

/**
 * MSW handlers for every admin operation, answering with the contract's examples
 * (`contract.gen.ts`, generated by `npm run gen:api`). Used by Vitest (`server.ts`) and by
 * `npm run dev:mock` in the browser (`browser.ts`).
 */

/** Matches the admin API on any origin, so the configured base URL does not matter. */
export const MOCK_API_PREFIX = '*/admin/v1';

export const operationIds = Object.keys(contractMocks) as OperationId[];

/** `/integrations/{integration_id}` -> `*\/admin/v1/integrations/:integration_id` */
export function mswPath(contractPath: string): string {
	return MOCK_API_PREFIX + contractPath.replace(/\{([^}]+)\}/g, ':$1');
}

const CROCKFORD = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
/** A contract-shaped request id (`req_` + 26 Crockford base32 chars). */
export function mockRequestId(): string {
	let s = 'req_';
	for (let i = 0; i < 26; i++) s += CROCKFORD[Math.floor(Math.random() * 32)];
	return s;
}

/** Literal path segments sort before `{param}` ones so `/snapshots/latest` wins over `/snapshots/{v}`. */
function byPathSpecificity(a: OperationId, b: OperationId): number {
	const sa = contractMocks[a].path.split('/');
	const sb = contractMocks[b].path.split('/');
	for (let i = 0; i < Math.max(sa.length, sb.length); i++) {
		const x = sa[i];
		const y = sb[i];
		if (x === undefined || y === undefined) return x === undefined ? -1 : 1;
		const px = x.startsWith('{');
		const py = y.startsWith('{');
		if (px !== py) return px ? 1 : -1;
	}
	return 0;
}

export interface HandlerOptions {
	/** Artificial latency (ms) so loading states are visible in `dev:mock`. */
	latencyMs?: number;
}

interface RespondInit {
	status?: number;
	headers?: Record<string, string>;
}

function respond(body: unknown, status: number, headers: Record<string, string> = {}): Response {
	const requestId =
		(body as Partial<AdminErrorEnvelope> | null)?.error?.request_id ?? mockRequestId();
	return HttpResponse.json(body as never, {
		status,
		headers: { [REQUEST_ID_HEADER]: requestId, ...headers }
	});
}

/** A handler for one operation answering with `body` (default: the contract example). */
export function mockOperation<Op extends OperationId>(
	op: Op,
	body?: OperationResponse<Op> | ((params: Record<string, string>) => OperationResponse<Op>),
	init: RespondInit & HandlerOptions = {}
): HttpHandler {
	const m = contractMocks[op];
	return http[m.method](mswPath(m.path), async ({ params }) => {
		if (init.latencyMs) await delay(init.latencyMs);
		const value =
			typeof body === 'function' ? body(params as Record<string, string>) : (body ?? m.example);
		return respond(value, init.status ?? m.status, { ...m.headers, ...init.headers });
	});
}

/**
 * A handler for one operation answering with the canonical error envelope. Defaults to the
 * contract's example for that status; pass `error` fields to override (e.g. a custom message).
 */
export function mockError<Op extends OperationId>(
	op: Op,
	status: number,
	error: Partial<AdminErrorEnvelope['error']> = {},
	init: HandlerOptions = {}
): HttpHandler {
	const m = contractMocks[op];
	const example = m.errors[String(status)] ?? contractMocks.getMe.errors['500'];
	if (!example) throw new Error(`no error example for ${op} ${status}`);
	return http[m.method](mswPath(m.path), async () => {
		if (init.latencyMs) await delay(init.latencyMs);
		return respond({ error: { ...example.error, ...error } }, status);
	});
}

/** A handler for one operation that never answers (to assert loading states). */
export function mockPending(op: OperationId): HttpHandler {
	const m = contractMocks[op];
	return http[m.method](mswPath(m.path), () => new Promise<never>(() => {}));
}

/** A handler for one operation whose request fails at the network level. */
export function mockNetworkError(op: OperationId): HttpHandler {
	const m = contractMocks[op];
	return http[m.method](mswPath(m.path), () => HttpResponse.error());
}

/**
 * Answers that keep the examples consistent with each other: the integration example has a draft
 * v8 (`has_draft`, `latest_version: 8`), and the contract's draft example IS that v8, so
 * `getIntegrationVersion` for v8 answers the draft rather than the v7 example.
 */
function coherentBody<Op extends OperationId>(op: Op) {
	if (op !== 'getIntegrationVersion') return undefined;
	const draft = contractMocks.createIntegrationDraft.example.integration_version;
	return ((params: Record<string, string>) =>
		params.version === String(draft.version)
			? draft
			: contractMocks.getIntegrationVersion.example) as unknown as (
		params: Record<string, string>
	) => OperationResponse<Op>;
}

/** One contract-example handler per admin operation, most specific paths first. */
export function createHandlers(opts: HandlerOptions = {}): HttpHandler[] {
	return [...operationIds]
		.sort(byPathSpecificity)
		.map((op) => mockOperation(op, coherentBody(op), { latencyMs: opts.latencyMs }));
}

export const handlers = createHandlers();

/**
 * The contract's `/me` example re-addressed to a dev-login identity (mock mode, HUB-253). Roles and
 * tenants come from the dev session; permissions keep the example's editor list for `editor` and
 * `admin` and are empty for read-only roles (the contract defines no per-role list).
 */
export function mockMe(user: SessionUser): OperationResponse<'getMe'> {
	const example = contractMocks.getMe.example;
	const writer = user.roles.some((r) => r === 'admin' || r === 'editor');
	return {
		...example,
		subject: user.subject,
		name: user.name ?? null,
		email: user.email ?? null,
		roles: [...user.roles],
		tenants: [...user.tenants],
		permissions: writer ? [...example.permissions] : []
	};
}
